int factorial(int n)
{
    int i, fact;

    fact = 1;
    for (i = 2; i <= n; i++) {
        fact *= i;
    }

    return fact;
}

int factorial(int n)
{
    if (n <= 1)
        return 1;
    else return
        n * factorial(n-1);
}

int fib(int n)
{
    if (n <= 1)
        return 1;
    else
        return fib(n-1) + fib(n-2);
}

